        CombatLabRequest combatRequest=new();CombatSimulationResult combatSingle;CombatBatchResult combatBatch,combatComparison;CombatMatrixResult combatMatrix;CombatCurveResult combatCurve;List<CombatBatchResult> policyComparisons=new();CombatTraceFilter combatFilter=CombatTraceFilter.All;int timelinePage,curveFightCount=100,curveStart=10,curveEnd=100,curveStep=10,matrixEnemyCount=3;string combatFingerprint;PlayerCombatPolicySO combatPolicy;
        void EnsureCombat()
        {
            EnsureEnemySelection();combatRequest.player=playerBuild;if(string.IsNullOrEmpty(combatRequest.enemyArchetypeId))combatRequest.enemyArchetypeId=EnemyDb.enemyArchetypes[0].stableId;if(string.IsNullOrEmpty(combatRequest.bossId))combatRequest.bossId=EnemyDb.bosses[0].stableId;combatRequest.config??=new CombatSimulationConfig();
